      const price = x => easeInfo.get(x.id)?.p ?? Infinity;
      const faixa = x => huntLevels.has(x.id) ? Math.floor(huntLevels.get(x.id) / 100) : Infinity;
      copy.sort((a,b) => faixa(a) - faixa(b) || tries(a) - tries(b) ||
        (huntLevels.get(a.id) ?? Infinity) - (huntLevels.get(b.id) ?? Infinity) ||
        price(a) - price(b) || a.id - b.id);
