    // Pokédex aberta na aba Top Catch: volta para a aba Pokédex em vez de clicar no menu (que fecharia o modal).
    const abaTop = many('button, [role="tab"]').find(b => /top\s*catch/i.test(label(b)));
    const abaDex = abaTop && many('button, [role="tab"]').find(b => b !== abaTop && /^pok[ée]dex$/i.test(label(b)) && !b.closest('nav.menu-topo'));
