    let ativo = true;
    const ok = await viagemSegura({ nome: state.goal.home, slug: state.goal.homeSlug || '', pokeId: null }, () => ativo, m => say(m));
    ativo = false;
    say(ok ? txt + '. De volta em ' + state.goal.home + '.' : txt + ', mas não consegui chegar em ' + state.goal.home + '. Verifique e mude na mão.', ok ? 'success' : 'warning');
