  // ===== Capturas desta semana (corrida semanal) =====
  // Início da semana: o jogo informa em estado.topCatch.s (ex.: '2026-10-18', horário de Brasília).
  function weekStart() {
    const s = window.__poke?.estado?.topCatch?.s;
    if (s && /^\d{4}-\d{2}-\d{2}$/.test(s)) return { key: s, t: Date.parse(s + 'T00:00:00-03:00') };
    const now = new Date(Date.now() - 3 * 3600000); // relógio de Brasília
    const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - now.getUTCDay()));
    const key = d.toISOString().slice(0, 10);
    return { key, t: Date.parse(key + 'T00:00:00-03:00') };
  }
  // Junta tudo o que mostra captura nesta semana: o que o próprio AutoDex registrou, o log de capturas
