    const val = pos => { const l = r.linhas.find(x => Number(x.pos ?? x.rank) === pos); return l ? Number(l.valor) : null; };
    const nick = String(window.__poke?.estado?.nick || '').toLowerCase();
    const eu = r.linhas.find(x => String(x.nick || '').toLowerCase() === nick);
    state.rankCatch = { key: weekStart().key, at: Date.now(), corte90: val(90), corte100: val(100), top1: val(1),
      linhas: r.linhas.length, minhaPos: eu ? Number(eu.pos ?? eu.rank) : null, meu: r.meu ?? null };
